"""#,
        option: [
            // Choose axis ticks based on UTC time.
            "useUTC": true,
            "title": [
                "text": "Intraday Chart with Breaks (Multiple Days)",
                "left": "center"
            ] as [String: Any],
            "tooltip": [
                "show": true,
                "trigger": "axis"
            ] as [String: Any],
            "grid": [
                "outerBounds": [
                    "top": "20%",
                    "bottom": "30%"
                ] as [String: Any]
            ] as [String: Any],
            "xAxis": [
                [
                    "type": "time",
                    "interval": 1000.0 * 60 * 30,   // 30 minutes
                    "axisLabel": [
                        "showMinLabel": true,
                        "showMaxLabel": true,
                        // PORT-NOTE: xAxis.axisLabel.formatter omitted — the JS closure formatted every
                        // tick as '{HH}:{mm}', except a tick sitting on a break (`opt.break`), which also
                        // got a second line '{weak|{dd}d}' with the day-of-month in grey. Without it the
                        // native pane falls back to the built-in time formatter, and the `rich.weak` style
                        // below is inert (nothing emits a {weak|...} tag).
                        "rich": [
                            "weak": [
                                "color": "#999"
                            ] as [String: Any]
                        ] as [String: Any]
                    ] as [String: Any],
                    "breaks": intradayBreaks1AxisBreaks,
                    "breakArea": [
                        "expandOnClick": false,
                        "zigzagAmplitude": 0.0,
                        "zigzagZ": 200.0,
                        "itemStyle": [
                            "borderColor": "none",
                            "opacity": 0.0
                        ] as [String: Any]
                    ] as [String: Any]
                ] as [String: Any]
            ],
            "yAxis": [
                "type": "value",
                "min": "dataMin"
            ] as [String: Any],
            "dataZoom": [
                [
                    "type": "inside",
                    "minValueSpan": intradayBreaks1DataZoomMinValueSpan
                ] as [String: Any],
                [
                    "type": "slider",
                    "top": "73%",
                    "minValueSpan": intradayBreaks1DataZoomMinValueSpan
                ] as [String: Any]
            ],
            "series": [
                [
                    "type": "line",
                    "symbolSize": 0.0,
                    "areaStyle": [:] as [String: Any],
                    "data": intradayBreaks1SeriesData
                ] as [String: Any]
            ]
        ])
}

private let intradayBreaks1DataZoomMinValueSpan: Double = 3600 * 1000

// The frozen `generateData()` output — the SAME text the reference pane splices into `_data`, so both
// panes plot the identical walk. `[timestamp, value]` per minute of each 09:30–16:00 UTC session, with a
